Q: &quot; &#39;_Service.xxxx&#39; isn&#39;t a valid override of &#39;Service.xxxx&#39; &quot; when generating retrofit code - Dart A: <p>Its a misleading error. Its most likely an incorrect import or syntax error, for me it was curly braces that I should not of had:</p>
<pre><code> INCORRECT:

 @POST('/top-headlines-change-this')
  Future&lt;HttpResponse&gt; saveShoppingListItem({
    @Body() GroceryItemModel groceryItem,
  });

  CORRECT:

     @POST('/top-headlines-change-this')
  Future&lt;HttpResponse&gt; saveShoppingListItem(
    @Body() GroceryItemModel groceryItem,
  );
</code></pre>

Q: How to create a searchable dropdown/autocomplete TextField in Jetpack Compose without the suggestion list stealing focus? A: <p><strong>This is a example of what you are trying to achieve , it is a floor dropdown example , so please try this.</strong></p>
<pre><code>/**
 * Searchable dropdown for floor selection
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun FloorDropdown(
    value: String,
    options: List&lt;String&gt;,
    floorMap: Map&lt;String, String&gt;,
    onValueChange: (displayFloor: String, rawFloor: String) -&gt; Unit,
    error: String = &quot;&quot;,
    onFieldFocusChange: () -&gt; Unit = {},
    onFieldFocusLoss: () -&gt; Unit = {}
) {
    var expanded by remember { mutableStateOf(false) }
    var searchQuery by remember(value) { mutableStateOf(value) }
    var lastValidValue by remember(value) { mutableStateOf(value) }
    var hasFocus by remember { mutableStateOf(false) }
    val focusManager = LocalFocusManager.current

    val filteredList = remember(searchQuery, options) {
        if (searchQuery.isEmpty()) options
        else options.filter { it.contains(searchQuery, ignoreCase = true) }
    }

    Column {
        Text(
            text = stringResource(Res.string.floor_required),
            fontSize = 14.sp,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            fontWeight = FontWeight.Medium,
            modifier = Modifier.padding(bottom = 6.dp)
        )

        ExposedDropdownMenuBox(
            expanded = expanded,
            onExpandedChange = { shouldExpand -&gt;
                if (shouldExpand) {
                    expanded = true
                } else if (!hasFocus) {
                    expanded = false
                }
            }
        ) {
            OutlinedTextField(
                value = searchQuery,
                onValueChange = {
                    searchQuery = it
                    expanded = true
                },
                placeholder = {
                    Text(
                        stringResource(Res.string.select_or_enter_floor),
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                    )
                },
                trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = expanded) },
                modifier = Modifier
                    .fillMaxWidth()
                    .menuAnchor(MenuAnchorType.PrimaryEditable, enabled = true)
                    .onFocusChanged { focusState -&gt;
                        hasFocus = focusState.isFocused
                        if (focusState.isFocused) {
                            onFieldFocusChange()
                            expanded = true
                        } else {
                            onFieldFocusLoss()
                            expanded = false
                            // Validate when field loses focus
                            if (searchQuery.isNotEmpty() &amp;&amp; !options.contains(searchQuery)) {
                                // Revert to last valid value
                                searchQuery = lastValidValue
                            } else if (options.contains(searchQuery)) {
                                lastValidValue = searchQuery
                            }
                        }
                    },
                shape = RoundedCornerShape(12.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    unfocusedBorderColor = if (error.isNotEmpty()) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.outline.copy(alpha = 0.5f),
                    focusedBorderColor = if (error.isNotEmpty()) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,
                    unfocusedContainerColor = MaterialTheme.colorScheme.surface,
                    focusedContainerColor = MaterialTheme.colorScheme.surface
                ),
                isError = error.isNotEmpty()
            )
            ExposedDropdownMenu(
                expanded = expanded &amp;&amp; filteredList.isNotEmpty(),
                onDismissRequest = { expanded = false },
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier
                    .clip(RoundedCornerShape(12.dp))
                    .background(
                        MaterialTheme.colorScheme.surface,
                        RoundedCornerShape(12.dp)
                    )
                    .border(
                        width = 1.dp,
                        color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f),
                        shape = RoundedCornerShape(12.dp)
                    )
            ) {
                filteredList.forEach { displayValue -&gt;
                    DropdownMenuItem(
                        text = {
                            Text(
                                displayValue,
                                fontSize = 15.sp,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        },
                        onClick = {
                            val rawFloor =
                                floorMap.entries.find { it.value == displayValue }?.key
                                    ?: displayValue
                            searchQuery = displayValue
                            lastValidValue = displayValue
                            onValueChange(displayValue, rawFloor)
                            expanded = false
                            focusManager.clearFocus()
                        },
                        modifier = Modifier
                            .padding(horizontal = 8.dp, vertical = 2.dp),
                        colors = androidx.compose.material3.MenuDefaults.itemColors(
                            textColor = MaterialTheme.colorScheme.onSurface,
                            leadingIconColor = MaterialTheme.colorScheme.primary,
                            trailingIconColor = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    )
                }
            }
        }
        if (error.isNotEmpty()) {
            Text(
                text = error,
                fontSize = 12.sp,
                color = MaterialTheme.colorScheme.error,
                modifier = Modifier.padding(top = 4.dp, start = 4.dp)
            )
        }
    }
}
</code></pre>
